package com.revayato.app;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;

/** Native watch-party lobby backed by Revayato's authenticated room API. */
public final class WatchPartyActivity extends Activity{
 static final String API=Config.API_BASE+"watch-party/rooms/";static final int BG=0xff050807,CARD=0xd919211c,LIME=0xffd8ff3e,WHITE=0xfff4f7f5,MUTED=0xffaab5ae;final ExecutorService io=Executors.newSingleThreadExecutor();LinearLayout body;ProgressBar busy;String code="";float zs=1f;
  @Override public void onCreate(Bundle b){super.onCreate(b);zs=Math.max(.95f,Math.min(1.35f,getResources().getConfiguration().fontScale));getWindow().setStatusBarColor(BG);renderLobby();String supplied=getIntent().getStringExtra("invite_code");if(supplied!=null&&!supplied.trim().isEmpty())join(supplied.trim());}
 void renderLobby(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setGravity(Gravity.CENTER_HORIZONTAL);body.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);body.setPadding(dp(20),dp(26),dp(20),dp(40));TextView live=text("●  WATCH TOGETHER",11,LIME,true);live.setGravity(Gravity.CENTER);live.setBackground(shape(0xff202d24,20));body.addView(live,new LinearLayout.LayoutParams(dp(174),dp(38)));TextView icon=text("",54,LIME,true);icon.setCompoundDrawablesWithIntrinsicBounds(0,R.drawable.ic_group,0,0);icon.setGravity(Gravity.CENTER);body.addView(icon,new LinearLayout.LayoutParams(-1,dp(88)));TextView title=text("سینمای شما، کنار دوستان",28,WHITE,true);title.setGravity(Gravity.CENTER);body.addView(title);TextView subtitle=text("اتاق بسازید، لینک دعوت بفرستید و یک فیلم را دقیقاً در یک لحظه تماشا کنید.",14,MUTED,false);subtitle.setGravity(Gravity.CENTER);body.addView(subtitle);LinearLayout features=new LinearLayout(this);features.setGravity(Gravity.CENTER);for(String item:new String[]{"پخش هم‌زمان","تا ۲۰ نفر","دعوت امن"}){TextView chip=text(item,11,0xffdce5df,true);chip.setGravity(Gravity.CENTER);chip.setBackground(shape(0xff202822,14));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,dp(38),1);cp.setMargins(dp(3),dp(14),dp(3),0);features.addView(chip,cp);}body.addView(features,new LinearLayout.LayoutParams(-1,-2));int id=getIntent().getIntExtra("content_id",0);if(id>0){Button create=primary("＋  ساخت اتاق برای این عنوان");create.setOnClickListener(v->create());body.addView(create,lp(60,22));}TextView divider=text("یا با کد دعوت وارد شوید",12,MUTED,false);divider.setGravity(Gravity.CENTER);body.addView(divider,lp(42,14));EditText input=new EditText(this);input.setHint("کد دعوت را اینجا وارد کنید");input.setSingleLine();input.setTextColor(WHITE);input.setHintTextColor(MUTED);input.setTextSize(14*zs);input.setGravity(Gravity.CENTER);input.setPadding(dp(16),0,dp(16),0);input.setBackground(shape(CARD,18));body.addView(input,lp(60,4));Button join=secondary("ورود به اتاق  ◀");join.setOnClickListener(v->join(input.getText().toString().trim()));body.addView(join,lp(56,10));busy=new ProgressBar(this);busy.setVisibility(View.GONE);body.addView(busy);scroll.addView(body);setContentView(scroll);}
 void create(){if(!signed()){login();return;}try{JSONObject b=new JSONObject().put("content_type",getIntent().getStringExtra("content_type")).put("content_id",getIntent().getIntExtra("content_id",0)).put("expires_in_minutes",240);request("POST",API,b,this::room);}catch(Exception e){error(e);}}
 void join(String value){if(!signed()){login();return;}if(!value.matches("[A-Za-z0-9_-]{20,32}")){Toast.makeText(this,"کد دعوت معتبر نیست",Toast.LENGTH_LONG).show();return;}request("POST",API+Uri.encode(value)+"/join/",new JSONObject(),this::room);}
void room(JSONObject j){code=j.optString("invite_code");body.removeAllViews();busy=new ProgressBar(this);busy.setVisibility(View.GONE);body.addView(busy);JSONObject content=j.optJSONObject("content"),host=j.optJSONObject("host");if(content==null)content=new JSONObject();boolean isHost=j.optBoolean("is_host");TextView status=text("●  اتاق فعال",12,LIME,true);status.setGravity(Gravity.CENTER);status.setBackground(shape(0xff1e3023,18));body.addView(status,new LinearLayout.LayoutParams(dp(126),dp(38)));TextView title=text(content.optString("title","تماشای گروهی"),24,WHITE,true);title.setGravity(Gravity.CENTER);body.addView(title,lp(70,8));LinearLayout people=new LinearLayout(this);people.setGravity(Gravity.CENTER);String hostName=host==null?"میزبان":host.optString("username","میزبان");TextView avatar=text(hostName.isEmpty()?"م":hostName.substring(0,1).toUpperCase(Locale.ROOT),22,BG,true);avatar.setGravity(Gravity.CENTER);avatar.setBackground(shape(LIME,50));people.addView(avatar,new LinearLayout.LayoutParams(dp(52),dp(52)));LinearLayout identity=new LinearLayout(this);identity.setOrientation(LinearLayout.VERTICAL);identity.addView(text("میزبان: "+hostName,14,WHITE,true));identity.addView(text(j.optInt("member_count",1)+" نفر در اتاق  •  "+(isHost?"شما میزبانید":"شما مهمانید"),12,MUTED,false));people.addView(identity,new LinearLayout.LayoutParams(0,-2,1));people.setPadding(dp(14),dp(10),dp(14),dp(10));people.setBackground(shape(CARD,18));body.addView(people,lp(78,10));TextView inviteTitle=text("کد ورود خصوصی",12,MUTED,true);inviteTitle.setGravity(Gravity.CENTER);body.addView(inviteTitle,lp(34,12));TextView invite=text(code,17,LIME,true);invite.setTextIsSelectable(true);invite.setGravity(Gravity.CENTER);invite.setLetterSpacing(.08f);invite.setBackground(shape(0xff111914,18));invite.setOnClickListener(v->copyCode());body.addView(invite,lp(66,0));LinearLayout inviteActions=new LinearLayout(this);Button copy=secondary("کپی کد");copy.setOnClickListener(v->copyCode());inviteActions.addView(copy,new LinearLayout.LayoutParams(0,dp(52),1));Button share=primary("دعوت دوستان");share.setOnClickListener(v->share());LinearLayout.LayoutParams shareLp=new LinearLayout.LayoutParams(0,dp(52),1);shareLp.setMargins(dp(8),0,0,0);inviteActions.addView(share,shareLp);LinearLayout.LayoutParams inviteLp=new LinearLayout.LayoutParams(-1,-2);inviteLp.setMargins(0,dp(8),0,dp(4));body.addView(inviteActions,inviteLp);String video=content.optString("video_url");if(!video.isEmpty()){Button play=primary(isHost?"▶  شروع نمایش برای همه":"▶  پیوستن به پخش هم‌زمان");JSONObject finalContent=content;play.setOnClickListener(v->startActivity(new Intent(this,PlayerActivity.class).putExtra("url",video).putExtra("title",finalContent.optString("title")).putExtra("content_type",finalContent.optString("type").equals("episode")?"series":"movie").putExtra("slug",finalContent.optString("slug")).putExtra("episode_id",finalContent.optString("type").equals("episode")?finalContent.optInt("id"):0).putExtra("subtitles",finalContent.optJSONArray("subtitle_tracks")==null?"[]":finalContent.optJSONArray("subtitle_tracks").toString()).putExtra("sources",streamUrls(finalContent.optJSONArray("stream_links")).toString()).putExtra("watch_party_code",code).putExtra("watch_party_host",isHost)));body.addView(play,lp(62,18));}Button refresh=secondary("↻  تازه‌سازی وضعیت اتاق");refresh.setOnClickListener(v->request("GET",API+Uri.encode(code)+"/",null,this::room));body.addView(refresh,lp(52,10));Button end=button(isHost?"پایان دادن به اتاق":"خروج از اتاق",0xff26191b,0xffffaab0);end.setOnClickListener(v->confirmExit(isHost));body.addView(end,lp(52,8));}
 JSONArray streamUrls(JSONArray links){JSONArray out=new JSONArray();if(links!=null)for(int i=0;i<links.length();i++){JSONObject link=links.optJSONObject(i);if(link!=null&&!link.optString("url").isEmpty())out.put(link.optString("url"));}return out;}
 void copyCode(){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("کد اتاق روایتو",code));Toast.makeText(this,"کد اتاق کپی شد",Toast.LENGTH_SHORT).show();}
 void confirmExit(boolean host){new AlertDialog.Builder(this).setTitle(host?"پایان اتاق؟":"خروج از اتاق؟").setMessage(host?"با پایان اتاق، پخش گروهی برای همه متوقف می‌شود.":"می‌توانید تا زمان فعال بودن اتاق دوباره با همین کد وارد شوید.").setNegativeButton("انصراف",null).setPositiveButton(host?"پایان اتاق":"خروج",(d,w)->request("POST",API+Uri.encode(code)+(host?"/end/":"/leave/"),new JSONObject(),x->finish())).show();}
 void share(){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,"با این کد در تماشای گروهی روایتو به من ملحق شو:\n"+code+"\nhttps://revayato.com/watch-party/"+code);startActivity(Intent.createChooser(i,"اشتراک دعوت"));}
 void login(){Toast.makeText(this,"ابتدا وارد حساب روایتو شوید",Toast.LENGTH_LONG).show();startActivity(new Intent(this,AuthActivity.class));}
 void request(String method,String url,JSONObject payload,java.util.function.Consumer<JSONObject> done){busy.setVisibility(View.VISIBLE);io.execute(()->{try{Session.Reply reply=Session.call(this,method,url,payload);if(!reply.ok())throw new IOException(reply.message());JSONObject result=reply.raw.trim().isEmpty()?new JSONObject():new JSONObject(reply.raw);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;busy.setVisibility(View.GONE);done.accept(result);});}catch(Exception e){runOnUiThread(()->{if(isFinishing()||isDestroyed())return;error(e);});}});}
 void error(Exception e){busy.setVisibility(View.GONE);Toast.makeText(this,e.getMessage()==null?"درخواست انجام نشد":e.getMessage(),Toast.LENGTH_LONG).show();}boolean signed(){return Session.signedIn(this);}
  TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size*zs);t.setTextColor(color);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);t.setLineSpacing(dp(2),1.08f);t.setPadding(dp(6),dp(7),dp(6),dp(7));if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 Button primary(String s){Button b=button(s,LIME,BG);b.setElevation(dp(5));return b;}
 Button secondary(String s){return button(s,CARD,WHITE);}
 Button button(String s,int bg,int color){return AppButtonFactory.create(this,s,bg,color,AppButtonFactory.borderFor(bg),zs);}
 GradientDrawable shape(int c,int r){GradientDrawable d;if(c==CARD){d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{c,0xb3111713});d.setStroke(dp(1),0x665f7868);}else{d=new GradientDrawable();d.setColor(c);}d.setCornerRadius(dp(r));return d;}
  LinearLayout.LayoutParams lp(int height,int top){int w=Math.min(dp(560),getResources().getDisplayMetrics().widthPixels-dp(44));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,Math.round(dp(height)*zs));p.setMargins(0,dp(top),0,dp(4));return p;}int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}@Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}
}
